<?php
namespace App\Services\Roster;
use App\Exports\RosterScheduleImportFailuresExport; use App\Models\ImportHistory; use App\Models\User; use App\Services\ImportHistory\ImportHistoryService; use Illuminate\Support\Facades\Storage; use Maatwebsite\Excel\Facades\Excel; use RuntimeException;
final class RosterScheduleImportPreviewService { public function __construct(private RosterScheduleWorkbookReader $reader,private RosterScheduleImportValidationService $validator,private ImportHistoryService $historyService){} public function preview(ImportHistory $history,User $actor):array {$path=(string)$history->file_path; $prefix='roster-imports/'.$history->import_id.'/'; if(!str_starts_with($path,$prefix)||str_contains($path,'..'))throw new RuntimeException('Path import tidak valid.'); $absolute=Storage::disk('local')->path('private/'.$path);$result=$this->validator->validate($this->reader->read($absolute)); if($result['is_valid'])$this->historyService->markAwaitingConfirmation($history->id,$result['summary']); else {$failure='roster-imports/'.$history->import_id.'/failures.xlsx';Excel::store(new RosterScheduleImportFailuresExport(array_values(array_filter($result['rows'],fn($r)=>$r['errors']))),'private/'.$failure,'local');$this->historyService->markValidationFailed($history->id,$result['summary'],$result['rows'],$failure);}return $result;} }
